{"command":"python3 << 'EOF'
import numpy as np
import os
import pickle

base_dir = '/srv/pickle_host'

# Check npz file for val_accuracy
print("="*60)
print("NPZ Files:")
print("="*60)
for f in ['model_01.npz', 'model_07.pkl']:
    if f.endswith('.npz'):
        try:
            data = np.load(os.path.join(base_dir, f), allow_pickle=True)
            val_acc = data['val_accuracy']
            print(f"{f}: val_accuracy = {val_acc}")
        except Exception as e:
            print(f"{f}: Error - {e}")
    elif f.endswith('.pkl'):
        try:
            with open(os.path.join(base_dir, f), 'rb') as file:
                data = pickle.load(file)
            if isinstance(data, dict):
                val_acc = data.get('val_accuracy')
                print(f"{f}: val_accuracy = {val_acc}")
            else:
                # It might be a single value
                val_acc = data
                print(f"{f}: val_accuracy = {val_acc}")
        except Exception as e:
            print(f"{f}: Error - {e}")

EOF"}
